(() => {
 const $=s=>document.querySelector(s);
 const section=document.createElement('section');section.className='profile-extra';section.innerHTML=`<p class="eyebrow dark">SUA CONTA PROTEGIDA</p><h2>Chave de recuperação</h2><p>Gere uma chave e guarde em um lugar seguro. Ela permite criar uma nova senha se você esquecer a atual. Cada chave funciona uma única vez; gerar outra substitui a anterior.</p><form id="recovery-key-form"><label>Confirme sua senha atual<input type="password" name="password" autocomplete="current-password" required maxlength="72"></label><button class="account-secondary" type="submit">Gerar minha chave</button></form><p id="security-status" role="status"></p><div id="recovery-result" hidden><p>Guarde agora. Esta chave não será exibida novamente.</p><code id="recovery-code"></code><button type="button" id="download-recovery" class="account-secondary">Baixar chave</button><button type="button" id="hide-recovery">Já guardei</button></div>`;
 $('#signed-account').append(section);
 const fav=document.createElement('section');fav.className='profile-extra';fav.id='meus-favoritos';fav.innerHTML='<p class="eyebrow dark">SUAS ESCOLHAS</p><h2>Meus favoritos</h2><div id="favorites-list" class="favorites-list" aria-live="polite">Carregando favoritos…</div>';section.before(fav);
 const recover=document.createElement('details');recover.className='password-recovery';recover.innerHTML=`<summary>Esqueci minha senha</summary><p>Use a chave de recuperação que você guardou no perfil. O e-mail de contato não recebe recuperação automática.</p><form id="reset-password-form"><label>Usuário<input name="username" autocomplete="username" autocapitalize="none" required maxlength="40"></label><label>Chave de recuperação<input name="code" autocomplete="off" spellcheck="false" required maxlength="80"></label><label>Nova senha<input name="password" type="password" autocomplete="new-password" minlength="8" maxlength="72" required></label><label>Confirme a nova senha<input name="confirmation" type="password" autocomplete="new-password" minlength="8" maxlength="72" required></label><button class="account-primary">Criar nova senha</button><p id="reset-status" role="status"></p></form><p class="account-hint">Sem a chave, a recuperação automática não está disponível. Após entrar, gere e guarde sua chave no perfil.</p>`;$('#auth-forms').append(recover);
 let savedCode='';
 async function request(path,data){const r=await fetch('/api/auth/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),b=await r.json();if(!r.ok)throw Error(b.error||'Não foi possível continuar.');return b;}
 $('#recovery-key-form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;$('#security-status').textContent='';try{const data=await request('recovery-key',{password:f.elements.password.value});f.reset();savedCode=data.code;$('#recovery-code').textContent=savedCode;$('#recovery-result').hidden=false;$('#security-status').textContent='Sua chave foi gerada.';}catch(err){$('#security-status').textContent=err.message;}finally{b.disabled=false;}};
 $('#download-recovery').onclick=()=>{const blob=new Blob(['Chave de recuperação — Up Smart Varginha\nUsuário: '+($('#account-username').textContent||'')+'\n'+savedCode+'\nGuarde em local seguro. Uso único. Não compartilhe.'],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='up-smart-chave-de-recuperacao.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 $('#hide-recovery').onclick=()=>{savedCode='';$('#recovery-code').textContent='';$('#recovery-result').hidden=true;};
 $('#reset-password-form').onsubmit=async e=>{e.preventDefault();const f=e.target,data=Object.fromEntries(new FormData(f));if(data.password!==data.confirmation){$('#reset-status').textContent='As senhas não são iguais.';return;}const b=f.querySelector('button');b.disabled=true;try{await request('reset-password',data);f.reset();$('#reset-status').textContent='Senha alterada. Entre acima com sua nova senha e gere uma nova chave no perfil.';$('#account-form').elements.username.value=data.username;$('#account-form').elements.password.focus();}catch(err){$('#reset-status').textContent=err.message;}finally{b.disabled=false;}};
})();
